<?php
declare(strict_types=1);
require_once __DIR__.'/planning_engine.php';
require_once __DIR__.'/operations.php';
function gszDashboardData(PDO $pdo,string $day):array {
 $r=['ready'=>false,'today'=>[],'appointments'=>[],'forecast'=>null,'overdue'=>0,'mail_reminders'=>[],'mail_unread'=>0,'mail_sync'=>null,'open_invoices'=>0,'unmatched'=>0,'receipts_without_bank'=>0,'source_warnings'=>0,'finance_due'=>null,'cashflows'=>null];
 $q=$pdo->prepare("SELECT t.*,p.name property_name,p.address FROM tasks t LEFT JOIN properties p ON p.id=t.property_id WHERE t.due_date=? ORDER BY (t.sort_order=0),t.sort_order,t.planned_order,t.start_time,t.id LIMIT 500");$q->execute([$day]);$r['today']=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM planning_appointments WHERE day=?'.(opsReady($pdo)?' AND cancelled_at IS NULL':'').' ORDER BY start_time,id');$q->execute([$day]);$r['appointments']=$q->fetchAll();$q=$pdo->prepare('SELECT COUNT(*) FROM tasks WHERE done=0 AND (due_date<? OR due_date IS NULL)');$q->execute([$day]);$r['overdue']=(int)$q->fetchColumn();$r['open_invoices']=(int)$pdo->query("SELECT COUNT(*) FROM invoices WHERE status='issued' AND document_kind='invoice'")->fetchColumn();$r['open_invoices']=(int)$pdo->query("SELECT COUNT(*) FROM invoices i LEFT JOIN (SELECT invoice_id,SUM(amount_cents) paid FROM finance_payments WHERE invoice_id IS NOT NULL GROUP BY invoice_id) p ON p.invoice_id=i.id WHERE i.status='issued' AND i.document_kind='invoice' AND CAST(ROUND(i.gross_total*100) AS SIGNED)>COALESCE(p.paid,0)")->fetchColumn();$settings=$pdo->query('SELECT * FROM planning_settings WHERE id=1')->fetch();$q=$pdo->prepare('SELECT start_time FROM planning_days WHERE day=?');$q->execute([$day]);$start=$q->fetchColumn()?:$settings['start_time'];$r['forecast']=planTimeline($r['today'],$r['appointments'],$settings,$start);$r['forecast_route']=false;try{require_once __DIR__.'/routing_store.php';$route=routeConfirmedDay($pdo,$day);if($route&&!$route['stale']){$r['forecast']=$route['route']['timeline'];$r['forecast_route']=$route['route']['source']!==null;}}catch(PDOException $e){}
 $calendarQuery='SELECT COUNT(*) FROM properties p WHERE NOT EXISTS(SELECT 1 FROM waste_sources s WHERE s.property_id=p.id AND s.valid_until>=? AND s.checked_at IS NOT NULL)';
 if((int)$pdo->query("SELECT COUNT(*) FROM app_migrations WHERE version='360_waste_connections'")->fetchColumn())$calendarQuery="SELECT COUNT(*) FROM properties p LEFT JOIN waste_connections c ON c.property_id=p.id WHERE (c.enabled=1 AND (c.status<>'connected' OR c.address_hash<>SHA2(p.address,256) OR NOT EXISTS(SELECT 1 FROM waste_sources s WHERE s.id=c.source_id AND s.checked_at IS NOT NULL AND s.valid_until>=?))) OR (c.property_id IS NULL AND (EXISTS(SELECT 1 FROM recurring_jobs j WHERE j.property_id=p.id AND j.rule_source IN ('routine_unverified','special_weekly')) OR EXISTS(SELECT 1 FROM waste_sources s WHERE s.property_id=p.id)) AND NOT EXISTS(SELECT 1 FROM waste_sources s WHERE s.property_id=p.id AND s.checked_at IS NOT NULL AND s.valid_until>=?))";
 $q=$pdo->prepare($calendarQuery);$q->execute(substr_count($calendarQuery,'?')===2?[$day,$day]:[$day]);$r['source_warnings']=(int)$q->fetchColumn();
 try{$r['mail_unread']=(int)$pdo->query("SELECT COUNT(*) FROM mail_messages m JOIN mail_folders f ON f.id=m.folder_id WHERE m.active=1 AND m.seen=0 AND f.name='INBOX'")->fetchColumn();$r['mail_sync']=$pdo->query('SELECT MAX(last_sync) FROM mail_folders')->fetchColumn();$r['mail_reminders']=$pdo->query("SELECT m.id,m.subject,m.sender FROM mail_messages m JOIN mail_folders f ON f.id=m.folder_id WHERE f.name='INBOX' AND m.active=1 AND m.important=1 AND m.answered=0 AND m.automatic_message=0 AND m.sent_at IS NOT NULL AND m.sent_at<UTC_TIMESTAMP()-INTERVAL 24 HOUR ORDER BY m.sent_at LIMIT 20")->fetchAll();$r['unmatched']=(int)$pdo->query('SELECT COUNT(*) FROM bank_transactions t WHERE NOT EXISTS(SELECT 1 FROM finance_payments p WHERE p.allocation_key=t.id)')->fetchColumn();$r['receipts_without_bank']=(int)$pdo->query("SELECT COUNT(*) FROM finance_receipts r WHERE r.status='confirmed' AND NOT EXISTS(SELECT 1 FROM finance_payments p WHERE p.receipt_id=r.id AND p.allocation_key IS NOT NULL)")->fetchColumn();$r['ready']=true;}catch(PDOException $e){}
 try{$q=$pdo->prepare('SELECT COUNT(*) FROM finance_recurrences WHERE active=1 AND next_due_date<=?');$q->execute([$day]);$r['finance_due']=(int)$q->fetchColumn();}catch(PDOException $e){}
 try{require_once __DIR__.'/finance_service.php';$r['cashflows']=financeSummary($pdo,substr($day,0,7).'-01',$day);}catch(PDOException $e){}
 return $r;
}
function gszDashboardPanel(PDO $pdo,array $config):void {
 try{$day=date('Y-m-d');$r=gszDashboardData($pdo,$day);}catch(Throwable $e){echo '<p class="notice">Tagesübersicht nicht verfügbar. Bitte Systemcheck öffnen.</p>';return;}
 $open=array_values(array_filter($r['today'],fn($t)=>!$t['done']));$done=count($r['today'])-count($open);$settings=$pdo->query('SELECT * FROM planning_settings WHERE id=1')->fetch();$now=(int)date('G')*60+(int)date('i');$forecastTasks=$open;foreach($forecastTasks as &$t)if($t['start_time']&&planMinute($t['start_time'])<$now)$t['start_time']=null;unset($t);$forecast=planTimeline($forecastTasks,$r['appointments'],$settings,planTime(max($now,planMinute($settings['start_time']))));$uncertain=(bool)array_filter($open,fn($t)=>planDuration($t)===null);$finished=!$open&&!array_filter($r['appointments'],fn($a)=>planMinute($a['end_time'])>$now);if($finished)$forecast['warnings']=[];
 $logged=$pdo->prepare('SELECT COUNT(*),COALESCE(SUM(duration_minutes),0) FROM work_logs WHERE performed_on=?');$logged->execute([$day]);[$logs,$actual]=$logged->fetch(PDO::FETCH_NUM);
 echo '<section class="surface"><h1>Heute · '.e(date('d.m.Y')).'</h1><p>Aktuelle Uhrzeit '.e(date('H:i')).' Uhr</p><div class="day-metrics">';foreach([['Offen',count($open)],['Erledigt',$done],['Verbleibende Planarbeit',$uncertain?'unbestimmt ('.$forecast['minutes'].' Min. bekannt)':$forecast['minutes'].' Min.'],['Geschätztes Ende',$finished?'keine Arbeit mehr':($uncertain?'offen':planTime($forecast['end']).' Uhr')]] as [$label,$value])echo '<div class="day-metric">'.e($label).'<strong>'.e((string)$value).'</strong></div>';echo '</div><p>Fahrtpuffer: '.(int)$forecast['buffer'].' Min. geschätzt. Erfasste Arbeitszeit: '.($logs?(int)$actual.' Min.':'nicht erfasst').'.</p><details><summary>Zeitprognose erklären</summary><p>Restprognose ab aktueller Uhrzeit. Planminuten sind keine tatsächlich geleisteten Stunden. Ohne bestätigte Routingdaten werden manuelle Schätzpuffer verwendet.</p></details>';
 foreach($forecast['warnings'] as $w)echo '<p class="error">'.e($w).'</p>';if($r['source_warnings'])echo '<p class="notice"><a href="waste.php">Für '.(int)$r['source_warnings'].' Objekte aktuelle Abfalltermine einrichten oder prüfen</a></p>';if(!filter_var($config['mail_enabled']??false,FILTER_VALIDATE_BOOLEAN))echo '<p class="notice"><a href="settings.php">E-Mail-Einrichtung noch abschließen</a></p>';if($r['overdue'])echo '<p class="notice"><a href="planner.php">'.$r['overdue'].' überfällige oder undatierte Aufgaben prüfen</a></p>';echo '<p><a href="planner.php">Heute öffnen</a> · <a href="planner.php?view=week">Woche prüfen</a> · <a href="appointments.php">Termine</a></p></section>';
 require_once __DIR__.'/automation.php';$jobs=gszAutomationStatus($pdo,$config);$base=array_values(array_filter($jobs,fn($j)=>$j['job_key']==='tasks'))[0];
 if($r['cashflows'])echo '<p>Bestätigte geschäftliche Zahlungsbewegungen im laufenden Monat: Einnahmen '.e(financeDecimal((int)$r['cashflows']['inflow'])).' EUR · Ausgaben '.e(financeDecimal((int)$r['cashflows']['outflow'])).' EUR. Keine vollständige steuerliche EÜR.</p>';
 echo '<section class="surface"><h2>Was Aufmerksamkeit braucht</h2><div class="attention-grid"><article><a href="mail.php">E-Mail</a><p>'.(int)$r['mail_unread'].' ungelesen · '.count($r['mail_reminders']).' wichtige unbeantwortet seit24Stunden</p><small>Letzter lokaler Abgleich: '.e($r['mail_sync']?:'noch keiner').' UTC</small></article><article><a href="receivables.php">Rechnungen und Zahlungen</a><p>'.(int)$r['open_invoices'].' offene Rechnungen · '.(int)$r['unmatched'].' Umsätze zur Prüfung</p></article><article><a href="accounting.php">Belege</a><p>'.(int)$r['receipts_without_bank'].' bestätigte Belege ohne Bankzuordnung</p></article><article><a href="system_check.php">Automatisierung</a><p>'.e($base['status']==='PASS'?'Letzte Aufgabenaktualisierung erfolgreich':($base['status']==='BLOCKED'?'Aufgabenaktualisierung fehlgeschlagen – prüfen':'Aufgabenaktualisierung noch nicht nachgewiesen')).'</p><small>'.e($base['last_success']?:'Noch kein erfolgreicher Lauf').' UTC</small></article></div></section>';
 $q=$pdo->prepare('SELECT day,start_time,end_time,title FROM planning_appointments WHERE day>? AND cancelled_at IS NULL ORDER BY day,start_time LIMIT 5');$q->execute([$day]);$upcoming=$q->fetchAll();if($upcoming){echo '<section class="surface"><h2>Nächste Termine</h2>';foreach($upcoming as $a)echo '<p>'.e($a['day'].' '.substr($a['start_time'],0,5).' · '.$a['title']).'</p>';echo '</section>';}
 require_once __DIR__.'/waste_widget.php';wasteWidget($pdo,$day);
 $pending=$pdo->prepare('SELECT COUNT(*) FROM waste_imports WHERE admin_id=? AND applied_at IS NULL AND created_at>=UTC_TIMESTAMP()-INTERVAL 1 DAY');$pending->execute([(int)($_SESSION['admin_id']??0)]);if((int)$pending->fetchColumn())echo '<p class="notice"><a href="waste.php">Neue Kalenderstände oder Fraktionen prüfen</a></p>';
 $groups=[];foreach($r['forecast']['rows']??[] as $row)$groups[$row['task']['property_name']??'Ohne Objekt'][]=$row;
 foreach($groups as $name=>$rows){echo '<section class="surface"><h2>'.e($name).'</h2>';foreach($rows as $row){$t=$row['task'];echo '<article class="day-task"><strong>'.e($t['title']).'</strong><p>'.e($t['address']??'').' · '.($row['duration']===null?'Dauer offen':(int)$row['duration'].' Min.').' · '.($t['done']?'Erledigt':e($row['start']===null?'Zeit offen':planTime($row['start']).'–'.planTime($row['end']??$row['start']))).'</p><form method="post"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="'.(int)$t['id'].'"><input type="hidden" name="row_version" value="'.(int)$t['row_version'].'"><input type="hidden" name="done" value="'.($t['done']?'0':'1').'"><button>'.($t['done']?'Wieder öffnen':'✓ Erledigt').'</button></form> <a href="task.php?id='.(int)$t['id'].'">Details / Notiz</a></article>';}echo '</section>';}
 foreach($r['appointments'] as $a)echo '<p class="notice">Termin '.e(substr($a['start_time'],0,5).'–'.substr($a['end_time'],0,5).' · '.$a['title']).'</p>';
}
function gszObjectPanel(PDO $pdo,int $id):void {
 try{$q=$pdo->prepare('SELECT DISTINCT d.id,d.title FROM documents d LEFT JOIN finance_receipts r ON r.document_id=d.id WHERE d.property_id=? OR r.property_id=? ORDER BY d.id DESC LIMIT 20');$q->execute([$id,$id]);$documents=$q->fetchAll();$q=$pdo->prepare('SELECT subject,id FROM mail_messages WHERE property_id=? ORDER BY id DESC LIMIT 20');$q->execute([$id]);$mail=$q->fetchAll();$q=$pdo->prepare('SELECT COALESCE(SUM(p.amount_cents),0) FROM finance_payments p JOIN invoices i ON i.id=p.invoice_id WHERE i.property_id=?');$q->execute([$id]);$revenue=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COALESCE(SUM(p.amount_cents),0) FROM finance_payments p JOIN finance_receipts r ON r.id=p.receipt_id WHERE r.property_id=?');$q->execute([$id]);$cost=(int)$q->fetchColumn();
 echo '<section class="card"><h2>Objektakte: Dokumente, Mail und bestätigte Zahlungen</h2><p>Zugeordnete Rechnungszahlungen '.e(number_format($revenue/100,2,',','.')).' EUR · Belegzahlungsbewegungen '.e(number_format($cost/100,2,',','.')).' EUR. Keine vollständige Objektkalkulation.</p>';foreach($documents as $d)echo '<p><a href="document_download.php?id='.(int)$d['id'].'">'.e($d['title']).'</a></p>';foreach($mail as $m)echo '<p><a href="mail.php?id='.(int)$m['id'].'">'.e($m['subject']).'</a></p>';echo '<p><a href="accounting.php">Belege/Zahlungshistorie</a></p></section>';
 }catch(PDOException $e){echo '<p>Erweiterte Objektakte nach Gesamtstand-Migration verfügbar.</p>';}
}
